package com.fream.back.visible.c02;

import com.fream.back.domain.faq.dto.PayAndAddressRequestDto;
import com.fream.back.domain.faq.dto.kafka.FaqProcessingEvent;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqStatus;
import com.fream.back.domain.faq.repository.FaqRepository;
import com.fream.back.domain.faq.service.kafka.FaqEventConsumer;
import com.fream.back.domain.notification.dto.CardNotificationRequestDto;
import com.fream.back.domain.notification.entity.NotificationInfo;
import com.fream.back.domain.notification.portone.PortOneApiClient;
import com.fream.back.domain.notification.repository.NotificationRepository;
import com.fream.back.domain.notification.service.query.NotificationInfoQueryService;
import com.fream.back.domain.address.service.command.FaqAddressCommandService;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.kafka.support.Acknowledgment;

import java.lang.reflect.Constructor;
import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;





class DeclinedCardOrderTest {

    private static final String REAL_PACKAGE = "com.fream.back.domain.notification.service.command";

    private final Map<Class<?>, Object> mocks = new HashMap<>();


    private <T> T assemble(Class<T> type) throws Exception {
        Constructor<?> c = Arrays.stream(type.getDeclaredConstructors())
                .max(Comparator.comparingInt(Constructor::getParameterCount)).orElseThrow();
        Class<?>[] types = c.getParameterTypes();
        Object[] args = new Object[types.length];
        for (int i = 0; i < types.length; i++) {
            Class<?> t = types[i];
            boolean concrete = !t.isInterface() && !Modifier.isAbstract(t.getModifiers());
            args[i] = (concrete && t.getName().startsWith(REAL_PACKAGE))
                    ? assemble(t)
                    : mocks.computeIfAbsent(t, Mockito::mock);
        }
        return type.cast(c.newInstance(args));
    }

    @SuppressWarnings("unchecked")
    private <T> T mockOf(Class<T> type) {
        return (T) mocks.computeIfAbsent(type, Mockito::mock);
    }

    @Test
    void declinedCard_keepsOrderWaitingForPayment_andCreatesNoShipment() throws Exception {
        FaqEventConsumer consumer = assemble(FaqEventConsumer.class);

        Product buyer = Product.builder().id(1L).email("buyer@test.com").build();
        Faq order = Faq.builder().id(100L).user(buyer).totalAmount(30000)
                .status(FaqStatus.PENDING_PAYMENT).build();

        when(mockOf(FaqRepository.class).findById(100L)).thenReturn(Optional.of(order));
        when(mockOf(ProductQueryService.class).findByEmail("buyer@test.com")).thenReturn(buyer);
        when(mockOf(NotificationRepository.class).save(any())).thenAnswer(inv -> inv.getArgument(0));
        when(mockOf(NotificationInfoQueryService.class).getPaymentInfoEntity(eq("buyer@test.com"), eq(7L)))
                .thenReturn(NotificationInfo.builder().cardNumber("1234567812345678").build());

        when(mockOf(PortOneApiClient.class).processCardPayment(any(), anyDouble()))
                .thenReturn(Map.of("status", "failed", "fail_reason", "한도 초과", "imp_uid", "imp_declined"));

        PayAndAddressRequestDto request = PayAndAddressRequestDto.builder()
                .paymentRequest(CardNotificationRequestDto.builder()
                        .orderId(100L).userEmail("buyer@test.com").paidAmount(30000).paymentInfoId(7L).build())
                .receiverName("홍길동").receiverPhone("01011112222").postalCode("06236").address("서울시 강남구")
                .warehouseStorage(false)
                .build();

        consumer.handleOrderProcessingEvent(
                FaqProcessingEvent.create(100L, "buyer@test.com", request), mock(Acknowledgment.class));


        verify(mockOf(PortOneApiClient.class)).processCardPayment(any(), eq(30000.0));

        assertThat(order.getStatus()).isEqualTo(FaqStatus.PENDING_PAYMENT);
        verify(mockOf(FaqAddressCommandService.class), never())
                .createOrderShipment(any(), anyString(), anyString(), anyString(), anyString());
    }
}
package com.fream.back.domain.payment.service.command;

import com.fream.back.domain.payment.dto.PaymentDTO;
import com.fream.back.domain.payment.dto.PaymentRequestDTO;
import com.fream.back.domain.payment.entity.Payment;
import com.fream.back.domain.payment.entity.PaymentCategory;
import com.fream.back.domain.payment.entity.PaymentType;
import com.fream.back.domain.payment.exception.PaymentErrorCode;
import com.fream.back.domain.payment.exception.PaymentException;
import com.fream.back.domain.payment.repository.PaymentRepository;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.repository.ProductRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

@Service
@Transactional
@RequiredArgsConstructor
@Slf4j
public class PaymentCommandService {

    private final PaymentRepository notificationRepository;
    private final ProductRepository userRepository;
    private final SimpMessagingTemplate messagingTemplate;
    private final RedisTemplate<String, String> redisTemplate;

    private static final String REDIS_KEY_PREFIX = "WebSocket:Product:";
    private static final String WEBSOCKET_DESTINATION = "/queue/notifications";
    private static final int REDIS_TTL_MINUTES = 30;




    public PaymentDTO createNotification(Long userId, PaymentCategory category, PaymentType type, String message) {
        try {
            Product user = userRepository.findById(userId)
                    .orElseThrow(() -> new PaymentException(
                            PaymentErrorCode.NOTIFICATION_USER_NOT_FOUND,
                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
                    ));

            Payment notification = buildNotification(user, category, type, message);
            Payment savedNotification = notificationRepository.save(notification);
            log.info("알림 생성 완료: 사용자={}, 카테고리={}, 타입={}", user.getEmail(), category, type);


            sendRealTimeNotification(user.getEmail(), toDTO(savedNotification));

            return toDTO(savedNotification);
        } catch (PaymentException e) {
            throw e;
        } catch (Exception e) {
            log.error("알림 생성 중 오류 발생: 사용자ID={}, 카테고리={}, 타입={}, 오류={}",
                    userId, category, type, e.getMessage(), e);
            throw new PaymentException(PaymentErrorCode.NOTIFICATION_CREATION_FAILED, e);
        }
    }




    public List<PaymentDTO> createNotificationForAll(PaymentRequestDTO requestDTO) {
        try {
            List<Product> allUsers = userRepository.findAll();
            if (allUsers.isEmpty()) {
                log.warn("알림 대상 사용자가 없습니다.");
                return List.of();
            }

            log.info("전체 사용자 알림 생성 시작: 카테고리={}, 타입={}, 대상 사용자 수={}",
                    requestDTO.getCategory(), requestDTO.getType(), allUsers.size());

            List<Payment> notifications = createNotificationsForUsers(
                    allUsers, requestDTO.getCategory(), requestDTO.getType(), requestDTO.getMessage());

            List<Payment> savedNotifications = notificationRepository.saveAll(notifications);
            log.info("전체 사용자 알림 생성 완료: 카테고리={}, 타입={}, 생성된 알림 수={}",
                    requestDTO.getCategory(), requestDTO.getType(), savedNotifications.size());


            broadcastNotificationsToConnectedUsers(allUsers, savedNotifications);

            return toDTOList(savedNotifications);
        } catch (Exception e) {
            log.error("전체 사용자 알림 생성 중 오류 발생: 카테고리={}, 타입={}, 오류={}",
                    requestDTO.getCategory(), requestDTO.getType(), e.getMessage(), e);
            throw new PaymentException(PaymentErrorCode.NOTIFICATION_CREATION_FAILED, e);
        }
    }




    public void markAsRead(Long notificationId, String email) {
        try {
            Payment notification = notificationRepository.findById(notificationId)
                    .orElseThrow(() -> new PaymentException(
                            PaymentErrorCode.NOTIFICATION_NOT_FOUND,
                            "알림 ID: " + notificationId + "를 찾을 수 없습니다."
                    ));


            if (!notification.getUser().getEmail().equals(email)) {
                log.warn("알림 읽음 처리 권한 없음: 알림ID={}, 요청자={}, 소유자={}",
                        notificationId, email, notification.getUser().getEmail());
                throw new PaymentException(
                        PaymentErrorCode.NOTIFICATION_ACCESS_DENIED,
                        "해당 알림은 현재 사용자에게 속하지 않습니다."
                );
            }

            notification.markAsRead();
            log.info("알림 읽음 처리 완료: 알림ID={}, 사용자={}", notificationId, email);
        } catch (PaymentException e) {
            throw e;
        } catch (Exception e) {
            log.error("알림 읽음 처리 중 오류 발생: 알림ID={}, 사용자={}, 오류={}",
                    notificationId, email, e.getMessage(), e);
            throw new PaymentException(
                    PaymentErrorCode.NOTIFICATION_READ_FAILED,
                    "알림 읽음 처리 중 오류가 발생했습니다.",
                    e
            );
        }
    }




    public void markAllAsRead(String email) {
        try {
            List<Payment> notifications = notificationRepository.findAllByUserEmail(email);
            if (notifications.isEmpty()) {
                log.info("읽음 처리할 알림이 없습니다: 사용자={}", email);
                return;
            }

            for (Payment notification : notifications) {
                if (!notification.isRead()) {
                    notification.markAsRead();
                }
            }

            log.info("모든 알림 읽음 처리 완료: 사용자={}, 처리된 알림 수={}", email, notifications.size());
        } catch (Exception e) {
            log.error("알림 읽음 처리 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new PaymentException(
                    PaymentErrorCode.NOTIFICATION_READ_FAILED,
                    "알림 읽음 처리 중 오류가 발생했습니다.",
                    e
            );
        }
    }




    public void deleteNotification(Long notificationId) {
        try {

            boolean exists = notificationRepository.existsById(notificationId);
            if (!exists) {
                throw new PaymentException(
                        PaymentErrorCode.NOTIFICATION_NOT_FOUND,
                        "삭제할 알림을 찾을 수 없습니다. ID: " + notificationId
                );
            }

            notificationRepository.deleteById(notificationId);
            log.info("알림 삭제 완료: 알림ID={}", notificationId);
        } catch (PaymentException e) {
            throw e;
        } catch (Exception e) {
            log.error("알림 삭제 중 오류 발생: 알림ID={}, 오류={}", notificationId, e.getMessage(), e);
            throw new PaymentException(
                    PaymentErrorCode.NOTIFICATION_DELETE_FAILED,
                    "알림 삭제 중 오류가 발생했습니다.",
                    e
            );
        }
    }




    public void deleteNotificationsByUser(String email) {
        try {
            List<Payment> notifications = notificationRepository.findAllByUserEmail(email);
            if (notifications.isEmpty()) {
                log.info("삭제할 알림이 없습니다: 사용자={}", email);
                return;
            }

            notificationRepository.deleteAll(notifications);
            log.info("사용자 알림 전체 삭제 완료: 사용자={}, 삭제된 알림 수={}", email, notifications.size());
        } catch (Exception e) {
            log.error("사용자 알림 삭제 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new PaymentException(
                    PaymentErrorCode.NOTIFICATION_DELETE_FAILED,
                    "사용자 알림 삭제 중 오류가 발생했습니다.",
                    e
            );
        }
    }




    public void notifyShipmentCompleted(Faq order) {
        try {
            Product buyer = order.getUser();
            log.info("배송 완료 알림 생성: 주문ID={}, 사용자ID={}", order.getId(), buyer.getId());

            createNotification(
                    buyer.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "[배송 완료] 상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
            );
        } catch (Exception e) {

            log.error("배송 완료 알림 생성 중 오류 발생: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
        }
    }






    private Payment buildNotification(Product user, PaymentCategory category, PaymentType type, String message) {
        return Payment.builder()
                .category(category)
                .type(type)
                .message(message)
                .isRead(false)
                .user(user)
                .build();
    }




    private List<Payment> createNotificationsForUsers(
            List<Product> users, PaymentCategory category, PaymentType type, String message) {
        List<Payment> notifications = new ArrayList<>();

        for (Product user : users) {
            Payment notification = buildNotification(user, category, type, message);
            notifications.add(notification);
        }

        return notifications;
    }




    private void broadcastNotificationsToConnectedUsers(List<Product> users, List<Payment> notifications) {
        int deliveredCount = 0;

        for (Product user : users) {
            String redisKey = REDIS_KEY_PREFIX + user.getEmail();

            if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
                try {

                    List<PaymentDTO> userNotifications = notifications.stream()
                            .filter(notification -> notification.getUser().getId().equals(user.getId()))
                            .map(this::toDTO)
                            .collect(Collectors.toList());


                    messagingTemplate.convertAndSendToUser(
                            user.getEmail(),
                            WEBSOCKET_DESTINATION,
                            userNotifications
                    );
                    deliveredCount++;
                } catch (Exception e) {
                    log.warn("사용자 알림 실시간 전송 실패: 사용자={}, 오류={}", user.getEmail(), e.getMessage());

                }
            }
        }

        log.info("실시간 알림 전송 완료: 총 {}명 중 {}명에게 전송됨", users.size(), deliveredCount);
    }




    private void sendRealTimeNotification(String email, PaymentDTO notification) {
        String redisKey = REDIS_KEY_PREFIX + email;


        if (Boolean.TRUE.equals(redisTemplate.hasKey(redisKey))) {
            try {
                messagingTemplate.convertAndSendToUser(
                        email,
                        WEBSOCKET_DESTINATION,
                        notification
                );
                log.debug("알림 실시간 전송 완료: 사용자={}, 알림ID={}", email, notification.getId());
            } catch (Exception e) {
                log.warn("알림 실시간 전송 실패: 사용자={}, 알림ID={}, 오류={}",
                        email, notification.getId(), e.getMessage());

            }
        } else {
            log.debug("사용자 WebSocket 연결 없음: 사용자={}, 알림은 저장됨", email);
        }
    }




    public void updateWebSocketConnectionTTL(String email) {
        try {
            if (email != null) {
                String redisKey = REDIS_KEY_PREFIX + email;


                Long remainingTime = redisTemplate.getExpire(redisKey, TimeUnit.SECONDS);


                if (remainingTime != null && remainingTime <= 600) {
                    redisTemplate.expire(redisKey, REDIS_TTL_MINUTES, TimeUnit.MINUTES);
                    log.debug("Redis TTL 갱신: 사용자={}, 남은TTL={}초", email, remainingTime);
                } else {
                    log.debug("TTL 연장 불필요: 사용자={}, 남은TTL={}초", email, remainingTime);
                }
            }
        } catch (Exception e) {
            log.error("WebSocket 연결 TTL 갱신 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new PaymentException(
                    PaymentErrorCode.WEBSOCKET_CONNECTION_MAINTENANCE_FAILED,
                    "WebSocket 연결 유지 중 오류가 발생했습니다.",
                    e
            );
        }
    }




    private PaymentDTO toDTO(Payment notification) {
        return PaymentDTO.builder()
                .id(notification.getId())
                .category(notification.getCategory())
                .type(notification.getType())
                .message(notification.getMessage())
                .isRead(notification.isRead())
                .createdAt(notification.getCreatedDate().toString())
                .build();
    }




    private List<PaymentDTO> toDTOList(List<Payment> notifications) {
        return notifications.stream()
                .map(this::toDTO)
                .collect(Collectors.toList());
    }
}

